# RWDM_INVERT: Invert: select everything not previously selected. The script rwdm_invert_script.txt is generated by rwdm_gen.py. The oracle is exact set logic on four Point objects (ids 1..4 at x = 1..4):
# each step lists the objects that a SelAll (or the current selection) reaches, and the ids must equal the expected set exactly (and the count line must agree).
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RWDM_INVERT_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rwdm_invert_script.txt" 2>&1)" || { echo "$RWDM_INVERT_OUT" | tail -40; echo "FAIL RWDM_INVERT_run: script exited non-zero"; fail=1; RWDM_INVERT_OUT=""; }
else
  RWDM_INVERT_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rwdm_invert_script.txt" 2>&1)" || { echo "$RWDM_INVERT_OUT" | tail -40; echo "FAIL RWDM_INVERT_run: script exited non-zero"; fail=1; RWDM_INVERT_OUT=""; }
fi
rwdm_invert_block() { awk -v name="$1" '$0 ~ ("Unknown command: RWDMBEGIN_" name "$") { on = 1; next } on && /Unknown command: RWDMBEGIN_/ { exit } on { print }' <<<"$RWDM_INVERT_OUT"; }
# rwdm_invert_ids STEP EXPECTED_IDS COUNT_LINE_OR_NONE DESC: the ids listed in the step, in order, are exactly EXPECTED_IDS ("-" = none); COUNT: the "N object(s) selected" line must say N
rwdm_invert_ids() {
  local blk got cnt; blk="$(rwdm_invert_block "$1")"
  got="$({ grep -oE '^history: Object [0-9]+ ' <<<"$blk" || true; } | sed -E 's/^history: Object ([0-9]+) /\1/' | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  cnt="$({ grep -oE '^history: [0-9]+ object\(s\) selected' <<<"$blk" || true; } | tail -1 | sed -E 's/^history: ([0-9]+) .*/\1/')"
  if [ "$got" = "$2" ] && { [ "$3" = none ] || [ "$cnt" = "$3" ]; }; then echo "ok   RWDM_INVERT_$1: $4 (ids: $got)"
  else echo "FAIL RWDM_INVERT_$1: $4 (listed ids '$got', expected '$2'; selected-count line '${cnt:-none}', expected '$3')"; fail=1; fi
}
rwdm_invert_ids one "1 2 4" none "with 3 selected, Invert selects exactly 1, 2 and 4"
rwdm_invert_ids none "1 2 3 4" none "with nothing selected, Invert selects all four"
rwdm_invert_ids all "-" none "with everything selected, Invert leaves nothing selected"
rwdm_invert_ids hidden "1 2" none "hidden objects are not picked up by Invert: with 4 hidden and 3 selected, Invert selects only 1 and 2"
